package vn.svframe.svframelib.api.crafting.ingredients; import vn.svframe.svframelib.api.crafting.uimanager.ProvidedUIFilter; import net.minecraft.item.ItemStack; public class ShapedIngredient extends SVFrameRecipeIngredient implements Cloneable { public int amountOfSuccess; private int verticalOffset,horizontalOffset; public ShapedIngredient(SVFrameIngredient i,int v,int h){super(i);verticalOffset=v;horizontalOffset=h;} public ShapedIngredient(ProvidedUIFilter f,int v,int h){super(f);verticalOffset=v;horizontalOffset=h;} public int getVerticalOffset(){return verticalOffset;} public void setVerticalOffset(int v){verticalOffset=v;} public int getHorizontalOffset(){return horizontalOffset;} public void setHorizontalOffset(int v){horizontalOffset=v;} public int getAmountOfSuccess(){return amountOfSuccess;} public boolean matches(ItemStack s){boolean ok=getIngredient().matches(s,null);if(ok)amountOfSuccess++;return ok;} public ShapedIngredient clone(){return new ShapedIngredient(getIngredient().clone(),verticalOffset,horizontalOffset);} public ShapedIngredient adapt(int v,int h){ShapedIngredient c=clone();c.verticalOffset+=v;c.horizontalOffset+=h;return c;} public ShapedIngredient adapt(int v,int h,int width,int height){ShapedIngredient c=adapt(v,h);if(c.overflowsWidthFromOffset(width,1)||c.overflowsHeightFromOffset(height,1))throw new IllegalArgumentException("ingredient overflow");return c;} public boolean overflowsWidthFromOffset(int width,int ignored){return horizontalOffset<0||horizontalOffset>=width;} public boolean overflowsHeightFromOffset(int height,int ignored){return verticalOffset<0||verticalOffset>=height;} }
